{
  "name": "网络套接字流接口",
  "name_en": "Socket Stream Interface",
  "manufacturer": "",
  "description": "一个非物理的软件通信组件，通过网络套接字提供通用字节流读写接口。在实验自动化中可用于与远程仪器、控制服务或实验进程交换原始数据，但证据不表明其对应某一特定物理设备。",
  "description_en": "A non-physical software communication component that provides generic byte-stream read/write access over an internet socket. In lab automation, it can be used to exchange raw data with remote instruments, control services, or experimental processes, but the evidence does not identify any specific physical instrument.",
  "actions": [
    {
      "action_name": "auto-write",
      "description": "向网络套接字流写入数据",
      "description_en": "Write data to the socket stream"
    },
    {
      "action_name": "auto-read",
      "description": "从网络套接字流读取数据",
      "description_en": "Read data from the socket stream"
    }
  ],
  "tag_hints": [
    "socket communication",
    "byte stream I/O",
    "network transport",
    "lab automation connectivity",
    "remote instrument communication"
  ]
}

